{{
  config(
    materialized='incremental',
    unique_key='event_id',
    incremental_strategy='merge',
    on_schema_change='append_new_columns'
  )
}}

with source as (

    select
        event_id,
        user_id,
        event_type,
        amount,
        event_ts,
        loaded_at
    from {{ source('app', 'events') }}

    {% if is_incremental() %}
    -- only scan recent data; lookback captures late-arriving rows
    where loaded_at >= (
        select dateadd('day', -3, max(loaded_at)) from {{ this }}
    )
    {% endif %}

)

select
    event_id,
    user_id,
    event_type,
    amount,
    event_ts,
    loaded_at
from source

