-- macros/test_no_date_gaps.sql
{% test no_date_gaps(model, column_name, partition_by) %}

with ordered as (
    select
        {{ partition_by }} as entity,
        {{ column_name }} as dt,
        lag({{ column_name }}) over (
            partition by {{ partition_by }}
            order by {{ column_name }}
        ) as prev_dt
    from {{ model }}
)

-- returns gap boundaries; any row = a missing date => test fails
select entity, prev_dt, dt
from ordered
where prev_dt is not null
  and datediff('day', prev_dt, dt) > 1

{% endtest %}
